USE university_explorer;
SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS funding_allocation (
  ETER_ID                           VARCHAR(6) NOT NULL PRIMARY KEY
  ,English_Institution_Name          VARCHAR(60)
  ,Institution_Name                  VARCHAR(62) NOT NULL
  ,Reference_year                    INTEGER  NOT NULL
  ,Country_Code                      VARCHAR(2) NOT NULL
  ,Name_of_the_city                  VARCHAR(22) NOT NULL
  ,Total_Current_revenues_EURO       NUMERIC(18,8)
  ,Basic_government_allocation_EURO  NUMERIC(18,8)
  ,Student_fees_funding_EURO         NUMERIC(19,10)
  ,Total_third_party_funding_EURO    NUMERIC(18,9)
  ,Personnel_expenditure_EURO        NUMERIC(18,9)
  ,RD_Expenditure_EURO               NUMERIC(20,11)
  ,Total_students_enrolled_ISCED_5_7 NUMERIC(18,12)
  ,Total_graduates_ISCED_5_7         NUMERIC(14,9)
  ,Total_graduates_at_ISCED_8        NUMERIC(6,1)
  ,Name                              VARCHAR(53) NOT NULL
  ,Overall_SCORE                     NUMERIC(4,1)
  ,AR_SCORE                          NUMERIC(4,1) NOT NULL
  ,ER_SCORE                          NUMERIC(4,1) NOT NULL
  ,FSR_SCORE                         NUMERIC(5,1) NOT NULL
  ,CPF_SCORE                         NUMERIC(4,1) NOT NULL
  ,IFR_SCORE                         NUMERIC(5,1)
  ,ISR_SCORE                         NUMERIC(5,1)
  ,EO_SCORE                          NUMERIC(4,1) NOT NULL
  ,SUS_SCORE                         NUMERIC(4,1)
  ,Rank                              VARCHAR(9) NOT NULL
  ,Size                              VARCHAR(2) NOT NULL
  ,Focus                             VARCHAR(2) NOT NULL
  ,Research                          VARCHAR(2) NOT NULL
  ,Status                            VARCHAR(22)
  ,QS_match_name                     VARCHAR(53)
  ,graduation_rate                   NUMERIC(19,17)
);
